import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-xl text-sm font-mono font-bold transition-all focus-visible:outline-none focus-visible:ring-2 disabled:pointer-events-none disabled:opacity-50 select-none cursor-pointer",
  {
    variants: {
      variant: {
        default: "bg-[#0078BF] text-white shadow-xs hover:bg-[#0078BF]/90 active:scale-97",
        secondary: "bg-[#F5EFE6] text-[#212121] border border-black/10 hover:bg-[#EADBCA] active:scale-97",
        outline: "border border-black/15 bg-white text-black shadow-xs hover:bg-black/5 active:scale-97",
        "paper-kinetic": "p-0 bg-transparent border-none shadow-none",
      },
      size: {
        default: "h-11 px-5 py-2",
        sm: "h-9 rounded-lg px-3 text-xs",
        lg: "h-12 rounded-xl px-8 text-base",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {
  dotShape?: 'circle' | 'square' | 'diamond';
  burstIntensity?: 'none' | 'gentle' | 'confetti';
  animationType?: 'snake-trail' | 'border-wrap' | 'glow-fade' | 'smooth-pulse' | 'wave-sweep' | 'hydraulic-pop' | 'ripple-wave' | 'stamp-press' | 'confetti-drift' | 'particle-vortex' | 'micro-chatter';
  inkColor?: string;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(({ className, variant = "default", size = "default", children, ...props }, ref) => {
  return (
    <button className={cn(buttonVariants({ variant, size, className }))} ref={ref} {...props}>
      {children}
    </button>
  );
});
Button.displayName = "Button";
export { buttonVariants };
